def cost_drag_pct(turnover_ratio, round_trip_cost_pct):
    """Annual cost drag as a percentage of capital."""
    return turnover_ratio * round_trip_cost_pct

def net_cagr(gross_cagr_pct, turnover_ratio, round_trip_cost_pct):
    return gross_cagr_pct - cost_drag_pct(turnover_ratio, round_trip_cost_pct)

# Weekly rotation strategy from the table above
print(round(net_cagr(12.0, 13.0, 0.30), 2))  # 8.1
